"use strict";(self.webpackChunkhudi=self.webpackChunkhudi||[]).push([[27952],{28453:(e,t,a)=>{a.d(t,{R:()=>i,x:()=>o});var s=a(96540);const r={},n=s.createContext(r);function i(e){const t=s.useContext(n);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),s.createElement(n.Provider,{value:t},e.children)}},57968:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/07/06/bringing-vector-search-to-the-lakehouse-with-apache-hudi","editUrl":"https://github.com/apache/hudi/edit/asf-site/website/blog/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi.mdx","source":"@site/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi.mdx","title":"Bringing Vector Search to the Lakehouse with Apache Hudi","description":"AI applications increasingly need to search data by meaning, not just by exact fields or keywords. Product descriptions, support tickets, documents, images, and other unstructured data are becoming first-class inputs to analytics and application workflows. But adding semantic search to lakehouse data has usually meant introducing a separate vector database, copying embeddings into it, and maintaining a sync pipeline to keep records, metadata, deletes, and updates aligned.","date":"2026-07-06T00:00:00.000Z","tags":[{"inline":true,"label":"vector","permalink":"/blog/tags/vector"},{"inline":true,"label":"vector search","permalink":"/blog/tags/vector-search"},{"inline":true,"label":"ai","permalink":"/blog/tags/ai"},{"inline":true,"label":"rag","permalink":"/blog/tags/rag"},{"inline":true,"label":"lakehouse","permalink":"/blog/tags/lakehouse"},{"inline":true,"label":"data lakehouse","permalink":"/blog/tags/data-lakehouse"},{"inline":true,"label":"apache spark","permalink":"/blog/tags/apache-spark"},{"inline":true,"label":"architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"querying","permalink":"/blog/tags/querying"}],"readingTime":15.96,"hasTruncateMarker":false,"authors":[{"name":"Rahil Chertara","url":"https://www.linkedin.com/in/rahil-chertara/","imageURL":"/assets/images/authors/rahil-chertara.jpg","key":"rahil-chertara","page":null},{"name":"Aditya Goenka","url":"https://www.linkedin.com/in/aditya-goenka-66a7b448/","imageURL":"/assets/images/authors/aditya-goenka.jpg","key":"aditya-goenka","page":null}],"frontMatter":{"title":"Bringing Vector Search to the Lakehouse with Apache Hudi","excerpt":"Apache Hudi\'s native VECTOR type and built-in vector search bring semantic search inside the lakehouse table itself, so embeddings stay consistent with the rest of the row instead of living in a separate vector database.","authors":["rahil-chertara","aditya-goenka"],"category":"deep-dive","image":"/assets/images/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi/1-hero-vector-search-lakehouse.png","tags":["vector","vector search","ai","rag","lakehouse","data lakehouse","apache spark","architecture","querying"]},"unlisted":false,"nextItem":{"title":"Building Indexes on a Moving Target","permalink":"/blog/2026/06/25/building-indexes-on-a-moving-target"}}')},84802:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>c,contentTitle:()=>o,default:()=>l,frontMatter:()=>i,metadata:()=>s,toc:()=>d});var s=a(57968),r=a(74848),n=a(28453);const i={title:"Bringing Vector Search to the Lakehouse with Apache Hudi",excerpt:"Apache Hudi's native VECTOR type and built-in vector search bring semantic search inside the lakehouse table itself, so embeddings stay consistent with the rest of the row instead of living in a separate vector database.",authors:["rahil-chertara","aditya-goenka"],category:"deep-dive",image:"/assets/images/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi/1-hero-vector-search-lakehouse.png",tags:["vector","vector search","ai","rag","lakehouse","data lakehouse","apache spark","architecture","querying"]},o=void 0,c={authorsImageUrls:[void 0,void 0]},d=[{value:"What is Semantic search?",id:"what-is-semantic-search",level:2},{value:"The need for both structured and unstructured data",id:"the-need-for-both-structured-and-unstructured-data",level:2},{value:"How does Hudi represent VECTOR?",id:"how-does-hudi-represent-vector",level:2},{value:"Querying with Hudi Vector Search",id:"querying-with-hudi-vector-search",level:2},{value:"Single-query vector search",id:"single-query-vector-search",level:3},{value:"Batch Vector Search",id:"batch-vector-search",level:3},{value:"How the brute-force implementation works",id:"how-the-brute-force-implementation-works",level:2},{value:"Future Vector index",id:"future-vector-index",level:2},{value:"Conclusion",id:"conclusion",level:2}];function h(e){const t={a:"a",admonition:"admonition",code:"code",em:"em",h2:"h2",h3:"h3",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,n.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"/assets/images/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi/1-hero-vector-search-lakehouse.png",alt:"Bringing Vector Search to the Lakehouse with Apache Hudi",width:"1000"})}),"\n",(0,r.jsxs)(t.admonition,{title:"TL;DR",type:"tip",children:[(0,r.jsx)(t.p,{children:"AI applications increasingly need to search data by meaning, not just by exact fields or keywords. Product descriptions, support tickets, documents, images, and other unstructured data are becoming first-class inputs to analytics and application workflows. But adding semantic search to lakehouse data has usually meant introducing a separate vector database, copying embeddings into it, and maintaining a sync pipeline to keep records, metadata, deletes, and updates aligned."}),(0,r.jsx)(t.p,{children:"Apache Hudi's native vector search brings that workflow closer to the table itself. Embeddings can live in the same Hudi table as the rest of the row, represented as a first-class VECTOR column and queried directly from SQL. This lets semantic search compose with structured filters, joins, updates, time travel, and incremental queries instead of requiring a separate sidecar system."}),(0,r.jsx)(t.p,{children:"Hudi exposes vector search through two SQL functions: hudi_vector_search for a single query vector and hudi_vector_search_batch for running top-k search across a table of query vectors. Embeddings can be stored as FLOAT, DOUBLE, or INT8, and compared using cosine, L2, or dot product distance. The initial implementation uses distributed brute-force KNN, while an optimized ANN vector index is being developed behind the same SQL interface so applications can adopt the API today and benefit from faster algorithms as they land."})]}),"\n",(0,r.jsx)(t.h2,{id:"what-is-semantic-search",children:"What is Semantic search?"}),"\n",(0,r.jsxs)(t.p,{children:["Consider an example of a user interacting with an ecommerce site that has millions of product listings. Typically in most data analytics systems, a user would have to craft a query on exact fields, such as ",(0,r.jsx)(t.code,{children:"category"}),", ",(0,r.jsx)(t.code,{children:"brand"}),", ",(0,r.jsx)(t.code,{children:"price"}),", ",(0,r.jsx)(t.code,{children:"size"}),", or ",(0,r.jsx)(t.code,{children:"inventory_status"})," in order to find a match."]}),"\n",(0,r.jsxs)(t.p,{children:['But many searches start with intent, and not direct fields. A user instead might search for "comfortable shoes for walking around Europe," even though there is no column called ',(0,r.jsx)(t.code,{children:"comfortable"}),' and no guarantee that the best listings use those exact words. Some products may say "travel sneakers," "all-day support," or "lightweight walking shoes" instead.']}),"\n",(0,r.jsxs)(t.p,{children:["To handle this, semantic search is a way to search by ",(0,r.jsx)(t.strong,{children:"meaning"}),' rather than by exact fields or keywords. It works by converting text, images, or other content into what are known as "vector embeddings".']}),"\n",(0,r.jsxs)(t.p,{children:["A ",(0,r.jsx)(t.strong,{children:"vector embedding"})," is a fixed-size array of numbers that represents the meaning of some piece of data, such as a product description, customer review, image, support message, or document chunk."]}),"\n",(0,r.jsx)(t.p,{children:"Embeddings are typically produced by machine learning models. For text, this might be an embedding model or LLM-based encoder that converts a sentence, paragraph, or document chunk into a vector. For images, it might be a vision model that converts visual content into the same kind of numerical representation."}),"\n",(0,r.jsx)(t.p,{children:"For example, a marketplace product description like:"}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{children:"Lightweight sneakers with cushioned soles for all-day walking\n"})}),"\n",(0,r.jsx)(t.p,{children:"might be converted into a vector that looks conceptually like this:"}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{children:"[0.12, -0.03, 0.44, ..., 0.08]\n"})}),"\n",(0,r.jsxs)(t.p,{children:["The individual numbers in an embedding are often called ",(0,r.jsx)(t.strong,{children:"features"}),". Each one helps place the original item somewhere in a high-dimensional space. For a product description, the model may learn features related to things like product type, use case, style, material, comfort, or activity. For an image, the features may capture patterns related to shape, color, texture, or visual similarity."]}),"\n",(0,r.jsx)(t.p,{children:'These features are usually not directly interpretable on their own. One number does not simply mean "comfort" or "travel." Instead, the full vector captures many learned signals together. What matters is how one vector relates to another. Products with similar meaning should produce vectors that are close together, even if the words are different.'}),"\n",(0,r.jsx)(t.p,{children:'That is what allows a search like "comfortable shoes for walking around Europe" to match products described as "travel sneakers," "supportive walking shoes," or "lightweight everyday trainers," even when those listings do not use the exact same words as the query.'}),"\n",(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"/assets/images/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi/2-semantic-search-example.png",alt:"A shopper query is embedded, compared against nearest product embeddings, and matched to semantically similar products such as travel sneakers and supportive walking shoes.",width:"1000"})}),"\n",(0,r.jsx)(t.h2,{id:"the-need-for-both-structured-and-unstructured-data",children:"The need for both structured and unstructured data"}),"\n",(0,r.jsxs)(t.p,{children:["The marketplace example shows why modern AI applications need both unstructured and structured data. The meaning of a product may live in descriptions, reviews, images, or support conversations, which can be converted into embeddings and searched semantically. But deciding whether a result is useful still depends on structured fields such as ",(0,r.jsx)(t.code,{children:"price"}),", ",(0,r.jsx)(t.code,{children:"size"}),", ",(0,r.jsx)(t.code,{children:"inventory_status"}),", ",(0,r.jsx)(t.code,{children:"shipping_region"}),", and ",(0,r.jsx)(t.code,{children:"seller_rating"}),"."]}),"\n",(0,r.jsx)(t.p,{children:"This pattern has become more important with the rise of LLM-powered applications. Search, recommendations, RAG, document intelligence, and agent workflows increasingly operate over text, images, and other unstructured data. But these applications still need the guarantees of structured data systems: filters, joins, updates, deletes, freshness, and governance."}),"\n",(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"/assets/images/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi/3-structured-unstructured-data.png",alt:"Unstructured data such as product descriptions, reviews, and images is embedded and combined with structured fields through SQL filters to produce a combined semantic and structured retrieval result.",width:"1000"})}),"\n",(0,r.jsx)(t.p,{children:"This is where the lakehouse becomes a natural fit. In many AI applications, the embedding is not an independent object. It is derived from the row itself: a product description, review, image, support conversation, document chunk, or some combination of fields. When that source data changes, the embedding needs to change with it. When a row is deleted, expired, corrected, or reprocessed, the corresponding embedding needs to follow the same lifecycle."}),"\n",(0,r.jsx)(t.p,{children:"A standalone vector database can be a good serving layer, especially for ultra-low-latency retrieval at very large scale. But if the source records live in the lakehouse, a separate vector database introduces another copy of the data. That copy has to be kept in sync with the table, including inserts, updates, deletes, schema changes, metadata filters, and backfills. Over time, the hard problem becomes less about computing nearest neighbors and more about maintaining consistency between the source data and the vector index."}),"\n",(0,r.jsx)(t.p,{children:"Hudi vector search is built around a simpler model: keep the original records, structured metadata, and embeddings together in the same table. In an ingestion pipeline, new and changed records can be processed incrementally, embeddings can be generated or refreshed from the latest source fields, and both the source data and vector columns can be committed together into Hudi. That makes the Hudi table the single source of truth for both analytics and semantic search."}),"\n",(0,r.jsxs)(t.p,{children:["For example, Hudi ",(0,r.jsx)(t.a,{href:"https://hudi.apache.org/docs/hoodie_streaming_ingestion/",children:"Streamer"})," can ingest changes from sources such as Kafka or cloud storage into a Hudi table. An embedding step can be added to the pipeline so that when product descriptions, reviews, images, or metadata change, the corresponding embeddings are updated as part of the same table workflow."]}),"\n",(0,r.jsx)(t.h2,{id:"how-does-hudi-represent-vector",children:"How does Hudi represent VECTOR?"}),"\n",(0,r.jsx)(t.p,{children:"Once embeddings are produced, they need to be stored in a table in a way that preserves their meaning. A plain array of numbers can store the values, but it does not tell the table system that the column is a fixed-dimensional vector intended for similarity search."}),"\n",(0,r.jsxs)(t.p,{children:["Hudi represents embeddings using a first-class logical type: ",(0,r.jsx)(t.code,{children:"VECTOR(dimension)"})," or ",(0,r.jsx)(t.code,{children:"VECTOR(dimension, element_type)"}),". The dimension value defines the fixed length of the vector. For example, ",(0,r.jsx)(t.code,{children:"VECTOR(768)"})," represents an embedding with 768 values."]}),"\n",(0,r.jsx)(t.p,{children:"A product catalog table can declare a vector column directly in SQL DDL:"}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{className:"language-sql",children:"CREATE TABLE products (\n  product_id string,\n  title string,\n  category string,\n  brand string,\n  price double,\n  inventory_status string,\n  description string,\n  description_embedding VECTOR(768)\n) USING hudi;\n"})}),"\n",(0,r.jsxs)(t.p,{children:["When the element type is omitted, Hudi uses ",(0,r.jsx)(t.code,{children:"FLOAT"})," by default. This is the most common representation for embeddings produced by text and image models. Hudi also supports ",(0,r.jsx)(t.code,{children:"DOUBLE"})," and ",(0,r.jsx)(t.code,{children:"INT8"})," for workloads that need higher precision or more compact storage."]}),"\n",(0,r.jsxs)(t.p,{children:["The storage difference becomes meaningful at scale. A ",(0,r.jsx)(t.code,{children:"VECTOR(768, FLOAT)"})," stores 3,072 bytes of raw vector values per row. The same vector represented as ",(0,r.jsx)(t.code,{children:"INT8"})," stores 768 bytes per row. Across millions or billions of rows, that difference affects table size, index size, and query cost."]}),"\n",(0,r.jsxs)(t.p,{children:["At the Hudi table level, both the SQL DDL form and the DataFrame API form describe the same logical column: a fixed-dimensional vector that can be validated, indexed, and used for vector search. At the physical storage layer, Hudi maps the logical vector type onto storage formats in a way that balances efficiency and interoperability. Readers that do not understand the Hudi vector logical type can still access the underlying data, while Hudi-aware readers can validate dimensions and treat the column as a single vector value. The DataFrame API equivalent and on-disk encoding are covered in the ",(0,r.jsx)(t.a,{href:"https://hudi.apache.org/docs/next/unstructured-data-quick-start-guide/",children:"docs"}),"."]}),"\n",(0,r.jsx)(t.p,{children:"Today, vector columns are supported as top-level columns. They cannot yet be nested inside structs, arrays, or maps. For data models that naturally contain multiple embeddings per entity, such as a product with many variants, the current pattern is to model each embedded item as its own row. Nested vector support can be added in the future as the type system and query semantics evolve."}),"\n",(0,r.jsx)(t.h2,{id:"querying-with-hudi-vector-search",children:"Querying with Hudi Vector Search"}),"\n",(0,r.jsx)(t.p,{children:"Once embeddings are stored in a Hudi table, they can be searched directly from SQL. Hudi provides two table-valued functions:"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.code,{children:"hudi_vector_search"})," for one query vector"]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.code,{children:"hudi_vector_search_batch"})," for many query vectors"]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"The difference is easiest to understand through the marketplace example."}),"\n",(0,r.jsxs)(t.p,{children:["A single-query search answers a question like: ",(0,r.jsx)(t.em,{children:"Given this shopper query, find the 10 most similar products."})]}),"\n",(0,r.jsxs)(t.p,{children:["A batch search answers a larger version of the same question: ",(0,r.jsx)(t.em,{children:"Given this table of many shopper queries, products, or documents, find the 10 most similar products for each row."})]}),"\n",(0,r.jsx)(t.p,{children:"So single-query search is one nearest-neighbor lookup. Batch search is the same lookup repeated for every row in another table, executed as one distributed job."}),"\n",(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"/assets/images/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi/4-querying-hudi-vector-search.png",alt:"hudi_vector_search returns the top nearest products for a single shopper query, while hudi_vector_search_batch runs the same lookup across every row of a query table in one distributed job.",width:"1000"})}),"\n",(0,r.jsx)(t.h3,{id:"single-query-vector-search",children:"Single-query vector search"}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.code,{children:"hudi_vector_search"})," takes the table to search, the embedding column, a query vector, and ",(0,r.jsx)(t.code,{children:"k"}),", plus a few optional arguments: the distance metric (",(0,r.jsx)(t.code,{children:"cosine"}),", ",(0,r.jsx)(t.code,{children:"l2"}),", or ",(0,r.jsx)(t.code,{children:"dot_product"}),"), a filter predicate applied before distance computation, and a ",(0,r.jsx)(t.code,{children:"max_distance"})," cutoff to drop weak matches. For a full list of parameters refer to the following ",(0,r.jsx)(t.a,{href:"https://hudi.apache.org/docs/next/unstructured-data-quick-start-guide/",children:"docs"}),"."]}),"\n",(0,r.jsx)(t.p,{children:'For example, a shopper might search for "wireless headphones for travel." The application converts that text into an embedding and searches the product catalog:'}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{className:"language-sql",children:"SELECT product_id, title, brand, price, _hudi_distance\nFROM hudi_vector_search(\n  'product_embeddings',\n  'embedding',\n  ARRAY(/* embedding of the shopper query */),\n  10,\n  'cosine',\n  'brute_force',\n  'category = ''electronics'' AND in_stock = true',\n  0.4\n);\n"})}),"\n",(0,r.jsx)(t.p,{children:"The filter is important. Since the first implementation uses brute-force search, reducing the candidate set before distance computation is one of the most effective ways to control latency. Searching 50 million product embeddings is expensive. Searching only the in-stock electronics products may reduce the search space to a much smaller subset."}),"\n",(0,r.jsxs)(t.p,{children:["The ",(0,r.jsx)(t.code,{children:"max_distance"})," argument is another practical control. It removes results whose distance is above the threshold, so the query does not return weak or irrelevant matches simply to fill the requested ",(0,r.jsx)(t.code,{children:"k"}),"."]}),"\n",(0,r.jsxs)(t.p,{children:["The output includes all corpus columns except the embedding column, plus ",(0,r.jsx)(t.code,{children:"_hudi_distance"}),". Results are ordered by distance ascending, so smaller values are more similar."]}),"\n",(0,r.jsx)(t.h3,{id:"batch-vector-search",children:"Batch Vector Search"}),"\n",(0,r.jsx)(t.p,{children:"Batch search is useful when you do not have just one query. Instead, you have a whole table of things that each need their own nearest-neighbor results."}),"\n",(0,r.jsxs)(t.p,{children:["That is what ",(0,r.jsx)(t.code,{children:"hudi_vector_search_batch"})," does: it runs top-k vector search for every row in a query table. It takes the same arguments as the single-query form, but searches with a whole ",(0,r.jsx)(t.code,{children:"query_table"})," (and its ",(0,r.jsx)(t.code,{children:"query_col"}),") instead of a single vector, returning the top ",(0,r.jsx)(t.em,{children:"k"})," corpus rows for each query row. See the ",(0,r.jsx)(t.a,{href:"https://hudi.apache.org/docs/next/unstructured-data-quick-start-guide/",children:"docs"})," for the full signature."]}),"\n",(0,r.jsx)(t.p,{children:"For example, suppose a marketplace wants to precompute related products every night. The input is not one shopper query. The input is a table of products:"}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{className:"language-sql",children:"SELECT\n  query_product_id,\n  product_id AS related_product_id,\n  title,\n  _hudi_distance,\n  _hudi_query_index\nFROM hudi_vector_search_batch(\n  'product_embeddings',\n  'embedding',\n  'query_products',\n  'query_embedding',\n  20,\n  'cosine',\n  'brute_force',\n  'in_stock = true',\n  0.4\n);\n"})}),"\n",(0,r.jsx)(t.p,{children:"The result contains the matching corpus rows, the query row metadata, and the computed distance. Hudi omits the embedding columns from the output because applications usually need the matching records and scores, not the raw vectors."}),"\n",(0,r.jsxs)(t.p,{children:["Batch search also adds ",(0,r.jsx)(t.code,{children:"_hudi_query_index"}),", which identifies which query row produced each result. This is useful because the output contains many groups of top-k results: one group per query row."]}),"\n",(0,r.jsx)(t.p,{children:"Put simply:"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.code,{children:"hudi_vector_search"})," returns the nearest rows for one query."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.code,{children:"hudi_vector_search_batch"})," returns the nearest rows for each query in a query table."]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"Batch search is especially useful for offline or scheduled workloads: related-product generation, duplicate detection, content matching, recommendation refreshes, and document similarity jobs."}),"\n",(0,r.jsx)(t.h2,{id:"how-the-brute-force-implementation-works",children:"How the brute-force implementation works"}),"\n",(0,r.jsx)(t.p,{children:"The previous section introduced the SQL interface for single-query and batch vector search. The next natural question is: what happens when those queries run?"}),"\n",(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"/assets/images/blog/2026-07-06-bringing-vector-search-to-the-lakehouse-with-apache-hudi/5-brute-force-vector-search.png",alt:"Distributed execution of a single-query vector search: the driver broadcasts the query vector to executors, each executor scans its Hudi table partitions and keeps a local top-k, and the driver merges local results into the global top-k.",width:"1000"})}),"\n",(0,r.jsx)(t.p,{children:"For a single-query search, the execution flow is:"}),"\n",(0,r.jsxs)(t.ol,{children:["\n",(0,r.jsx)(t.li,{children:"Spark receives the query vector and broadcasts it to executors."}),"\n",(0,r.jsx)(t.li,{children:"Each executor scans its portion of the corpus."}),"\n",(0,r.jsx)(t.li,{children:"For each row, the executor computes the distance between the query vector and the row's embedding."}),"\n",(0,r.jsxs)(t.li,{children:["Each executor keeps only its local top ",(0,r.jsx)(t.code,{children:"k"})," matches."]}),"\n",(0,r.jsx)(t.li,{children:"The driver merges those local top-k results into the final global top-k result."}),"\n"]}),"\n",(0,r.jsxs)(t.p,{children:["This keeps executor memory bounded by ",(0,r.jsx)(t.code,{children:"k"}),", rather than by the total size of the corpus. Even if an executor scans millions of rows, it only needs to keep the best candidates it has seen so far."]}),"\n",(0,r.jsx)(t.p,{children:"The main cost is distance computation. If the query searches 50 million embeddings, Hudi has to compare the query vector against 50 million candidate vectors. If the query first filters the corpus down to 200,000 relevant rows, the amount of distance computation drops dramatically."}),"\n",(0,r.jsxs)(t.p,{children:["That is why the filter argument in ",(0,r.jsx)(t.code,{children:"hudi_vector_search"})," matters. It lets applications apply structured predicates before vector distance computation runs. For example, an ecommerce query may search only products where ",(0,r.jsx)(t.code,{children:"category = 'electronics'"})," and ",(0,r.jsx)(t.code,{children:"in_stock = true"}),", rather than searching the entire product catalog."]}),"\n",(0,r.jsx)(t.p,{children:'Batch search follows the same idea, but repeats it for many query vectors in one distributed job. Instead of asking, "what are the nearest products for this one shopper query?", batch search asks, "what are the nearest products for every row in this query table?"'}),"\n",(0,r.jsx)(t.p,{children:"For example, a nightly recommendation job might take every active product as a query row and find the top 20 related products for each one. Hudi compares each query embedding against the filtered corpus, ranks matches per query, and returns one group of top-k results for each query row."}),"\n",(0,r.jsx)(t.p,{children:"Because batch search multiplies the amount of work by the number of query rows, the candidate set matters even more. A small query table searched against a well-filtered corpus can be practical. A large query table searched against an unfiltered corpus can become expensive quickly. This is why batch search is best suited for offline or scheduled workloads such as related-product generation, duplicate detection, content matching, and recommendation refreshes."}),"\n",(0,r.jsxs)(t.p,{children:["The ",(0,r.jsx)(t.code,{children:"max_distance"})," argument is useful in both single-query and batch search. It removes weak matches above a distance threshold before returning results. In batch jobs, this can reduce output size significantly because each query row may otherwise produce up to ",(0,r.jsx)(t.code,{children:"k"})," results, even when some matches are not useful."]}),"\n",(0,r.jsx)(t.p,{children:"This is why vector search becomes more powerful when it is integrated with table semantics. Many applications do not want nearest neighbors across all data. They want nearest neighbors within a meaningful slice of the table: active products, recent documents, records for a specific customer, listings in a region, or items that pass business rules. It is most useful when combined with the same filtering, pruning, and table layout techniques that data systems already use to reduce the amount of data read."}),"\n",(0,r.jsx)(t.h2,{id:"future-vector-index",children:"Future Vector index"}),"\n",(0,r.jsxs)(t.p,{children:["The SQL interface is designed to stay stable as new algorithms are added. Today, ",(0,r.jsx)(t.code,{children:"algorithm => 'brute_force'"})," uses a distributed linear scan. In the future, indexed implementations such as IVF-PQ can replace the scan with an index lookup plan."]}),"\n",(0,r.jsxs)(t.p,{children:["In that model, Hudi would use a ",(0,r.jsx)(t.a,{href:"https://github.com/apache/hudi/issues/18676?issue=apache%7Chudi%7C18851",children:"vector index"})," to produce candidate record IDs and distances, then join those candidates back to the table to return the same output shape. Applications written against the current table-valued function interface should not need to change when switching from brute-force search to indexed search."]}),"\n",(0,r.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,r.jsx)(t.p,{children:"For the past few years, adding semantic search to a lakehouse application usually meant adding a separate vector database, copying embeddings into it, and maintaining a sync pipeline between the two systems. That architecture works, but it adds operational complexity at exactly the point where correctness matters: keeping records, embeddings, metadata, deletes, and updates aligned."}),"\n",(0,r.jsx)(t.p,{children:"Hudi vector search takes a different approach. Embeddings are stored in the same table as the rest of the row, with the same schema, snapshots, updates, and table services. Vector search becomes part of the query layer instead of a separate sidecar system that has to be synchronized with the lakehouse."}),"\n",(0,r.jsxs)(t.p,{children:["The first implementation focuses on making this model simple and usable: a ",(0,r.jsx)(t.code,{children:"VECTOR"})," type for embeddings, SQL functions for single-query and batch vector search, and integration with Hudi's existing table semantics. This is especially useful for RAG, document intelligence, recommendation refreshes, deduplication, clustering, and similarity search jobs where correctness, freshness, and SQL composability matter as much as raw serving latency."]}),"\n",(0,r.jsxs)(t.p,{children:["The best way to understand the model is to try it directly. Start with ",(0,r.jsx)(t.a,{href:"https://hudi.apache.org/blog/2026/06/07/apache-hudi-release-1-2-announcement/",children:"Hudi 1.2"}),", create a table with a ",(0,r.jsx)(t.code,{children:"VECTOR"})," column, load a small set of embeddings, and run your first ",(0,r.jsx)(t.code,{children:"hudi_vector_search"})," query. From there, try adding structured filters, experimenting with ",(0,r.jsx)(t.code,{children:"hudi_vector_search_batch"}),", or materializing similarity results back into a Hudi table."]}),"\n",(0,r.jsx)(t.p,{children:"If you are building AI applications on lakehouse data, this is the core idea to test: semantic search does not have to live outside the table. With Hudi, embeddings, metadata, updates, and search can move through the same data system."})]})}function l(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}}}]);